function showView(name){if(!viewNames[name])return; $$('.page').forEach(p=>p.classList.toggle('active',p.id==='view-'+name)); $$('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name)); $('#crumb').textContent=viewNames[name]; window.scrollTo({top:0,behavior:'smooth'}); if(name==='calendar')renderCalendar(); if(name==='clients')renderClients(); if(name==='social-accounts')renderSocialAccounts(); if(name==='composer')loadComposerAccounts(); if(name==='analytics')loadSocialAnalytics(); if(name==='inbox')loadSocialInbox(); if(name==='approvals')renderApprovals();}
