function renderCalendar(){
 const grid=$('#calendar-grid'); if(!grid)return; const year=calDate.getFullYear(),month=calDate.getMonth();$('#calendar-month').textContent=calDate.toLocaleDateString('en-US',{month:'long',year:'numeric'});
 const names=['SUN','MON','TUE','WED','THU','FRI','SAT'];grid.innerHTML=names.map(n=>`<div class="calendar-day day-name">${n}</div>`).join('');
 const first=new Date(year,month,1).getDay(),days=new Date(year,month+1,0).getDate(),prevDays=new Date(year,month,0).getDate();const today='2026-10-16';
 for(let i=0;i<42;i++){let d=i-first+1,other=false,dayNum=d;if(d<1){dayNum=prevDays+d;other=true}else if(d>days){dayNum=d-days;other=true}const date=new Date(year,month,dayNum+(d<1?-(first):d>days?days:0));let iso=`${year}-${String(month+1).padStart(2,'0')}-${String(dayNum).padStart(2,'0')}`;let ev=allPosts().filter(p=>p.date===iso);grid.insertAdjacentHTML('beforeend',`<div class="calendar-day ${iso===today?'today':''}" style="${other?'opacity:.42':''}"><div class="day-num">${dayNum}</div>${ev.slice(0,2).map(p=>`<div class="calendar-event ${p.cls||'event-purple'}" title="${escapeHtml(p.title)}">${escapeHtml(p.client.split(' ')[0])}: ${escapeHtml(p.title)}</div>`).join('')}${ev.length>2?`<small>+${ev.length-2} more</small>`:''}</div>`);if(i===41)break;}
}
