function renderApprovals(){const el=$('#approval-table');if(!el)return;el.innerHTML=approvals.map((item,index)=>`<div class="approval-table-row" data-approval="${index}"><div class="approval-post"><div class="client-avatar ${item.color}">${escapeHtml(item.initials)}</div><div><b>${escapeHtml(item.title)}</b><small>${item.providerPostId?'Provider approval request':'Sample approval'}</small></div></div><div class="approval-client"><b>${escapeHtml(item.client)}</b><small>${escapeHtml(item.channel)}</small></div><div class="submitted-by">${escapeHtml(item.by)}</div><div><span class="status review">${escapeHtml(item.status)}</span></div><div class="approval-actions"><button class="approve" data-approve="${index}" ${item.status==='Approved'?'disabled':''}>✓ Approve</button><button data-edit="${index}">Review</button></div></div>`).join('');$$('[data-approve]').forEach(button=>button.addEventListener('click',async()=>{const item=approvals[+button.dataset.approve];if(item.providerPostId){const client=clients.find(candidate=>candidate.id===item.clientId);if(!client){toast('The client workspace for this approval no longer exists.');return;}try{await callSocialApi({action:'approve',clientId:client.id,postId:item.providerPostId});}catch(error){toast(error.message);return;}}item.status='Approved';scheduleWorkspaceSave();toast(item.providerPostId?`“${item.title}” approved and released.`:`“${item.title}” sample approval updated.`);renderApprovals();}));$$('[data-edit]').forEach(button=>button.addEventListener('click',()=>{const item=approvals[+button.dataset.edit];showView('composer');$('#post-copy').value=`${item.title}\n\nAdd your caption here…`;updatePreview();scheduleWorkspaceSave();toast('Draft opened in Publishing Studio');}));}
