function insertAtCursor(el,text){const start=el.selectionStart,end=el.selectionEnd;el.value=el.value.slice(0,start)+text+el.value.slice(end);el.focus();el.selectionStart=el.selectionEnd=start+text.length;updatePreview();}
let uploadedMedia=[];
$('#upload-zone')?.addEventListener('click',()=>$('#media-input').click());
$('#media-input')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')&&!file.type.startsWith('video/')){toast('Choose an image or video file.');e.target.value='';return;}if(file.size>50*1024*1024){toast('Media must be 50 MB or smaller.');e.target.value='';return;}uploadedMedia=[];const previewUrl=URL.createObjectURL(file),preview=$('#preview-media');if(file.type.startsWith('image/'))preview.innerHTML=`<img src="${previewUrl}" alt="Uploaded preview" style="width:100%;height:100%;object-fit:cover">`;else preview.innerHTML=`<div class="media-placeholder">▶<small>${escapeHtml(file.name)}</small></div>`;$('#upload-zone').querySelector('b').textContent=file.name;if(!supabaseClient||!activeUser){scheduleWorkspaceSave();toast('Local preview only. Sign in and configure storage to publish media.');return;}const extension=(file.name.match(/\.([a-z0-9]{1,8})$/i)?.[1]||'bin').toLowerCase(),path=`${activeUser.id}/${crypto.randomUUID()}.${extension}`;try{const{error}=await supabaseClient.storage.from('social-media').upload(path,file,{contentType:file.type||'application/octet-stream',upsert:false});if(error)throw error;const{data}=supabaseClient.storage.from('social-media').getPublicUrl(path);uploadedMedia.push({path,url:data.publicUrl});scheduleWorkspaceSave();toast('Media uploaded and ready to publish.');}catch(error){console.error('Media upload failed:',error);toast('Media preview loaded, but upload failed. Check Supabase Storage setup.');}});
function savePost(status,providerResponse=null){const copy=$('#post-copy').value.trim();if(!copy){toast('Add post copy before saving.');$('#post-copy').focus();return;}const client=$('#client-select').value,clientWorkspace=clients.find(item=>item.name===client),date=$('#schedule-date').value||'2026-10-19',time=$('#schedule-time').value||'10:00',channel=$$('.account-select input[type=checkbox]:checked').map(input=>input.value).join(', ')||'Social',initials=client.split(' ').map(word=>word[0]).join('').slice(0,2),providerPost=providerResponse?.posts?.[0]||providerResponse,providerPostId=providerPost?.id||providerResponse?.id||'';const post={day:new Date(date+'T12:00:00').toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'}).toUpperCase(),time:new Date(`2000-01-01T${time}`).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}),client,initials,color:client==='Bright School Kits'?'coral':client==='Revere Rum'?'gold':client==='STEM Story Kits'?'green-bg':'blue-bg',title:copy.split('\n')[0].slice(0,75),channel,status,date,providerPostId,providerUrl:providerPost?.postIds?.[0]?.postUrl||'',cls:client==='Bright School Kits'?'event-coral':client==='Revere Rum'?'event-gold':client==='STEM Story Kits'?'event-green':'event-purple'};savedPosts.unshift(post);renderUpcoming();renderCalendar();if(status==='In Review'){approvals.unshift({title:post.title,client,clientId:clientWorkspace?.id,channel,by:'You',status:'In Review',initials,color:post.color,providerPostId});renderApprovals();}toast(status==='Scheduled'?'Post scheduled through connected accounts.':status==='In Review'?'Post sent to the provider approval queue.':'Draft saved in this browser.');}
