const workspaceStorageKey='signaldesk-workspace-v1';
const supabaseConfig=window.SIGNALDESK_CONFIG||{};
const supabaseConfigured=Boolean(supabaseConfig.url&&supabaseConfig.anonKey);
const supabaseClient=supabaseConfigured&&window.supabase?.createClient?window.supabase.createClient(supabaseConfig.url,supabaseConfig.anonKey):null;
let activeUser=null;
let workspaceSaveTimer;
function setStorageStatus(message){const label=$('#storage-status-label');if(label)label.textContent=message;}
function collectWorkspaceState(){const fields=$$('.settings-form .field');return{clients,savedPosts,approvals,uploadedMedia,draft:$('#post-copy')?.value||'',settings:{name:fields[0]?.value||'PK Works Studio',timezone:fields[1]?.value||'Eastern Time (US & Canada)',approval:fields[2]?.value||'Require approval before publishing',approvalNotifications:$('.settings-form input[type=checkbox]')?.checked??true,weeklyDigest:$$('.settings-form input[type=checkbox]')[1]?.checked??true}};}
function applyWorkspaceState(state={}){if(Array.isArray(state.clients))clients.splice(0,clients.length,...state.clients.map(client=>({...client,id:client.id||`client-${client.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}`})));if(Array.isArray(state.savedPosts))savedPosts=state.savedPosts;if(Array.isArray(state.approvals))approvals.splice(0,approvals.length,...state.approvals);if(Array.isArray(state.uploadedMedia))uploadedMedia=state.uploadedMedia.filter(media=>media&&typeof media.path==='string'&&typeof media.url==='string'&&media.url.startsWith('https://'));if(typeof state.draft==='string'&&$('#post-copy'))$('#post-copy').value=state.draft;const fields=$$('.settings-form .field'),settings=state.settings||{};if(fields[0])fields[0].value=settings.name||'PK Works Studio';if(fields[1])fields[1].value=settings.timezone||'Eastern Time (US & Canada)';if(fields[2])fields[2].value=settings.approval||'Require approval before publishing';const checkboxes=$$('.settings-form input[type=checkbox]');if(checkboxes[0])checkboxes[0].checked=settings.approvalNotifications??true;if(checkboxes[1])checkboxes[1].checked=settings.weeklyDigest??true;renderClientSelects();}
function scheduleWorkspaceSave(showToast=false){clearTimeout(workspaceSaveTimer);workspaceSaveTimer=setTimeout(()=>saveWorkspaceState(showToast),350);}
async function saveWorkspaceState(showToast=false){const state=collectWorkspaceState();try{if(supabaseConfigured){if(!activeUser){setStorageStatus('Sign in to sync');return;}if(!supabaseClient)throw new Error('Supabase SDK failed to load');const{error}=await supabaseClient.from('workspace_state').upsert({user_id:activeUser.id,state,updated_at:new Date().toISOString()});if(error)throw error;setStorageStatus('Cloud synced');}else{localStorage.setItem(workspaceStorageKey,JSON.stringify(state));setStorageStatus('Saved in browser');}if(showToast)toast('Workspace settings saved.');}catch(error){console.error('Workspace save failed:',error);setStorageStatus('Save failed');toast('Could not save workspace changes. Check your connection and setup.');}}
function renderWorkspace(){renderUpcoming();renderCalendar();renderClients();renderApprovals();renderAssets();updatePreview();const publishingNote=$('.composer-panel .demo-note');if(publishingNote)publishingNote.textContent='Publishing requires a linked account and configured provider credentials. Scheduled times use your local time zone.';const footer=$('.app-footer');if(footer){$('span:first-child',footer).textContent='SignalDesk · Social workspace';$('span:last-child',footer).textContent='Overview and calendar examples use sample data';}}
async function loadWorkspaceState(){let state={},migrateLocalState=false;if(supabaseConfigured){if(!supabaseClient){setStorageStatus('Supabase SDK unavailable');openAuthDialog();return;}const{data:{session},error:sessionError}=await supabaseClient.auth.getSession();if(sessionError)throw sessionError;activeUser=session?.user||null;if(!activeUser){setStorageStatus('Sign in to sync');openAuthDialog();return;}const{data,error}=await supabaseClient.from('workspace_state').select('state').eq('user_id',activeUser.id).maybeSingle();if(error)throw error;if(data){state=data.state||{};migrateLocalState=Array.isArray(state.clients)&&state.clients.some(client=>!client.id);}else{try{state=JSON.parse(localStorage.getItem(workspaceStorageKey)||'{}');}catch{}migrateLocalState=true;}setStorageStatus('Cloud synced');$('#auth-button').textContent=activeUser.email||'Account';}else{try{state=JSON.parse(localStorage.getItem(workspaceStorageKey)||'{}');}catch{try{localStorage.removeItem(workspaceStorageKey);}catch{}}setStorageStatus('Saved in browser');}applyWorkspaceState(state);renderWorkspace();if(migrateLocalState)await saveWorkspaceState();}
function openAuthDialog(){const dialog=$('#auth-dialog');if(!dialog)return;const configured=supabaseConfigured&&supabaseClient;$('#auth-description').textContent=configured?'Sign in to sync your workspace across devices.':'Add your Supabase project URL and anon key in js/config.js, then run the SQL in supabase/schema.sql. Browser storage remains active until cloud sync is configured.';$('#auth-sign-in').hidden=!configured;$('#auth-sign-up').hidden=!configured;$('#auth-sign-out').hidden=!activeUser;$('#auth-email').hidden=!configured;$('#auth-password').hidden=!configured;$('#auth-message').textContent='';if(!dialog.open)dialog.showModal();}
const SOCIAL_NETWORKS=[['bluesky','Bluesky','＠'],['facebook','Facebook','f'],['gmb','Google Business Profile','G'],['instagram','Instagram','◎'],['linkedin','LinkedIn','in'],['pinterest','Pinterest','P'],['reddit','Reddit','r'],['snapchat','Snapchat','◉'],['telegram','Telegram','➤'],['threads','Threads','@'],['tiktok','TikTok','♪'],['twitter','X','𝕏'],['whatsapp','WhatsApp','◉'],['youtube','YouTube','▶']];
const socialAccountCache=new Map();
let activeConversation=null;
function renderClientSelects(){const selects=[$('#client-select'),$('#accounts-client-select'),$('#analytics-client-select'),$('#live-inbox-client-select')].filter(Boolean),options=clients.map(client=>`<option value="${escapeHtml(client.name)}">${escapeHtml(client.name)}</option>`).join('');selects.forEach(select=>{const selected=select.value;select.innerHTML=options;if(clients.some(client=>client.name===selected))select.value=selected;});}
function selectedClient(selectId){const select=$(selectId);return clients.find(client=>client.name===select?.value)||clients[0]||null;}
async function callSocialApi(payload){if(!supabaseConfigured||!supabaseClient)throw new Error('Configure Supabase sign-in before connecting social accounts.');const{data:{session}}=await supabaseClient.auth.getSession();if(!session?.access_token)throw new Error('Sign in to connect social accounts.');const response=await fetch('/api/social',{method:'POST',headers:{'content-type':'application/json',authorization:`Bearer ${session.access_token}`},body:JSON.stringify(payload)});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||result.message||'Social integration request failed.');return result;}
function renderSocialAccountCards(accounts=[]){const grid=$('#social-account-grid');if(!grid)return;grid.innerHTML=SOCIAL_NETWORKS.map(([platform,label,icon])=>{const account=accounts.find(item=>item.platform===platform),linked=Boolean(account?.linked);return `<div class="social-account-card ${linked?'is-connected':'is-unlinked'}"><span class="social-platform-icon ${platform}">${icon}</span><div class="social-account-copy"><b>${label}</b><small>${linked?escapeHtml(account.displayName||account.username||'Connected'):platform==='twitter'&&account?.available===false?'Developer app required':'Not connected'}</small></div><span class="social-account-state ${linked?'connected':'disconnected'}">${linked?'Connected':'Not linked'}</span></div>`;}).join('');}
async function refreshSocialAccounts(){const client=selectedClient('#accounts-client-select');if(!client)return;const status=$('#social-accounts-status');if(!activeUser||!supabaseConfigured){if(status)status.textContent='Sign in and configure Supabase to connect social profiles.';renderSocialAccountCards();return;}if(status)status.textContent='Checking linked accounts…';try{const data=await callSocialApi({action:'accounts',clientId:client.id});socialAccountCache.set(client.id,data.accounts||[]);renderSocialAccountCards(data.accounts||[]);const linked=(data.accounts||[]).filter(account=>account.linked).length;if(status)status.textContent=`${linked} connected network${linked===1?'':'s'} for ${client.name}.`;}catch(error){renderSocialAccountCards(socialAccountCache.get(client.id)||[]);if(status)status.textContent=error.message;}}
function renderSocialAccounts(){renderClientSelects();renderSocialAccountCards(socialAccountCache.get(selectedClient('#accounts-client-select')?.id)||[]);refreshSocialAccounts();}
async function startSocialAccountLink(){const client=selectedClient('#accounts-client-select');if(!client)return;const popup=window.open('about:blank','_blank');if(!popup){toast('Allow pop-ups to connect social accounts.');return;}try{const result=await callSocialApi({action:'connect',clientId:client.id});const target=new URL(result.url);if(target.hostname!=='profile.ayrshare.com')throw new Error('The provider returned an unexpected linking URL.');popup.location.href=target.href;popup.opener=null;const poll=window.setInterval(()=>{if(popup.closed){window.clearInterval(poll);refreshSocialAccounts();}},900);}catch(error){popup.close();$('#social-accounts-status').textContent=error.message;toast(error.message);}}
async function loadComposerAccounts(){const box=$('.account-select');if(!box)return;const client=selectedClient('#client-select');if(!client)return;box.innerHTML='<p class="account-empty">Loading connected accounts…</p>';if(!activeUser||!supabaseConfigured){box.innerHTML='<p class="account-empty">Sign in and connect a client account to publish.</p>';return;}try{const data=await callSocialApi({action:'accounts',clientId:client.id});socialAccountCache.set(client.id,data.accounts||[]);const linked=(data.accounts||[]).filter(account=>account.linked);box.innerHTML=linked.length?linked.map(account=>{const network=SOCIAL_NETWORKS.find(item=>item[0]===account.platform),label=network?.[1]||account.platform,icon=network?.[2]||'•';return `<label class="account-choice"><input type="checkbox" value="${account.platform}"><span class="platform-icon ${account.platform}">${icon}</span><span><b>${label}</b><small>${escapeHtml(account.displayName||account.username||client.name)}</small></span><span class="connected">Connected</span></label>`;}).join(''):'<p class="account-empty">No social profiles are linked for this client yet. Connect them in Social Accounts.</p>';}catch(error){box.innerHTML=`<p class="account-empty">${escapeHtml(error.message)}</p>`;}}
async function publishSocialPost(requiresApproval=false){const client=selectedClient('#client-select'),text=$('#post-copy').value.trim(),platforms=$$('.account-select input[type=checkbox]:checked').map(input=>input.value);if(!text){toast('Add post copy before publishing.');$('#post-copy').focus();return;}if(!client||!platforms.length){toast('Choose a client and at least one connected account.');return;}const date=$('#schedule-date').value,time=$('#schedule-time').value;let scheduleDate;try{scheduleDate=new Date(`${date}T${time}`).toISOString();}catch{toast('Choose a valid schedule date and time.');return;}try{const result=await callSocialApi({action:'publish',clientId:client.id,text,platforms,mediaUrls:uploadedMedia.map(media=>media.url),scheduleDate,requiresApproval});const outcomes=result.postIds||result.posts?.flatMap(item=>item.postIds||[])||[];if(result.status==='error'||(outcomes.length&&outcomes.every(item=>item.status==='error')))throw new Error(result.errors?.[0]?.message||'The provider could not publish to the selected networks.');savePost(requiresApproval?'In Review':'Scheduled',result);scheduleWorkspaceSave();toast(requiresApproval?'Post submitted to the provider approval queue.':'Post scheduled through the social API.');}catch(error){toast(error.message);}}
function ensureAnalyticsPanel(){let panel=$('#live-analytics-panel');if(panel)return panel;const view=$('#view-analytics');panel=document.createElement('div');panel.id='live-analytics-panel';panel.className='panel live-analytics-panel';const stats=$('.analytics-stats',view);view.insertBefore(panel,stats||view.firstChild);return panel;}
function addPanelClientSelector(panelId,selectorId){const panel=$(`#${panelId}`),header=$('.panel-header',panel);if(!panel||!header)return;let select=$(`#${selectorId}`);if(!select){select=document.createElement('select');select.id=selectorId;select.className='field panel-client-select';header.append(select);}renderClientSelects();}
function metricDisplay(value){if(value&&typeof value==='object'&&typeof value.total==='number')return value.total.toLocaleString();if(typeof value==='number')return value.toLocaleString();return null;}
async function loadSocialAnalytics(){const panel=ensureAnalyticsPanel();let body=$('#live-analytics-body');if(!body){panel.innerHTML='<div class="panel-header"><div><h2>Connected account analytics</h2><p>Live results from linked client profiles.</p></div><span class="live-label">LIVE DATA</span></div><div class="live-analytics-body" id="live-analytics-body">Loading connected account metrics…</div>';addPanelClientSelector('live-analytics-panel','analytics-client-select');body=$('#live-analytics-body');}renderClientSelects();const client=selectedClient('#analytics-client-select');if(!activeUser||!supabaseConfigured){body.textContent='Sign in and configure the social API to load real analytics.';return;}if(!client){body.textContent='Add a client workspace first.';return;}body.textContent=`Loading ${client.name} analytics…`;try{const accounts=await callSocialApi({action:'accounts',clientId:client.id}),platforms=(accounts.accounts||[]).filter(account=>account.linked).map(account=>account.platform);if(!platforms.length){body.textContent=`No accounts are connected for ${client.name}.`;return;}const data=await callSocialApi({action:'analytics',clientId:client.id,platforms,quarters:1}),rows=platforms.map(platform=>{const result=data[platform]||{},analytics=Array.isArray(result.analytics)?result.analytics[0]||{}:result.analytics||{},metrics=Object.entries(analytics).filter(([key,value])=>/followers|subscriber|impression|view|like|comment|engagement|share/i.test(key)&&metricDisplay(value)!==null).slice(0,4);return `<div class="live-analytics-row"><b>${escapeHtml(SOCIAL_NETWORKS.find(item=>item[0]===platform)?.[1]||platform)}</b><span>${metrics.map(([key,value])=>`${escapeHtml(key.replace(/([A-Z])/g,' $1'))}: ${metricDisplay(value)}`).join(' · ')||'Connected; no metrics returned'}</span><small>${escapeHtml(result.lastUpdated||'')}</small></div>`;}).join('');body.innerHTML=rows||'No metrics returned.';}catch(error){body.textContent=error.message;}}
function ensureLiveInbox(){let panel=$('#live-inbox-panel');if(panel)return panel;const view=$('#view-inbox'),heading=$('.page-heading',view);panel=document.createElement('div');panel.id='live-inbox-panel';panel.className='panel live-inbox-panel';panel.innerHTML='<div class="panel-header"><div><h2>Connected messages</h2><p id="live-inbox-status">Messages load from supported linked accounts.</p></div><button class="secondary-button" id="refresh-live-inbox" type="button">↻ Refresh</button></div><div class="live-inbox-layout"><div class="live-inbox-list" id="live-inbox-list"></div><div class="live-inbox-detail"><div id="live-inbox-message" class="live-inbox-message">Select a conversation to view it.</div><textarea id="live-reply-text" placeholder="Write a reply…"></textarea><button class="primary-button" id="send-live-reply" type="button">Send reply ↗</button></div></div><section class="live-comments"><div class="live-comments-heading"><h2>Post comments</h2><p>Load comments for a post published through a connected profile.</p></div><div class="live-comments-controls"><input id="comment-post-id" class="field" placeholder="Ayrshare post ID"><select id="comment-platform" class="field"><option value="facebook">Facebook</option><option value="instagram">Instagram</option><option value="linkedin">LinkedIn</option><option value="twitter">X</option><option value="youtube">YouTube</option><option value="tiktok">TikTok</option><option value="bluesky">Bluesky</option><option value="reddit">Reddit</option></select><button class="secondary-button" id="load-post-comments" type="button">Load comments</button></div><div id="live-comments-list" class="live-comments-list"></div><div class="live-comment-compose"><textarea id="post-comment-text" placeholder="Write a comment on this post…"></textarea><button class="primary-button" id="send-post-comment" type="button">Post comment</button></div></section>';view.insertBefore(panel,heading?.nextSibling||view.firstChild);const sample=$('.inbox-panel',view);if(sample)sample.style.display='none';return panel;}
function hideSampleInboxNote(){const view=$('#view-inbox'),note=$('.inbox-panel + .demo-note',view),headingAction=$('.page-heading .secondary-button',view);if(note)note.style.display='none';if(headingAction)headingAction.style.display='none';}
async function loadSocialInbox(){ensureLiveInbox();const status=$('#live-inbox-status'),list=$('#live-inbox-list');if(!activeUser||!supabaseConfigured){status.textContent='Sign in and configure the social API to load real messages.';list.textContent='No connected inbox yet.';return;}status.textContent='Loading supported conversations…';const client=clients[0];if(!client){status.textContent='Add a client workspace first.';return;}try{const accountData=await callSocialApi({action:'accounts',clientId:client.id}),platforms=(accountData.accounts||[]).filter(account=>account.linked&&['facebook','instagram','twitter','whatsapp'].includes(account.platform)).map(account=>account.platform);const responses=await Promise.all(platforms.map(platform=>callSocialApi({action:'messages',clientId:client.id,platform})));const latest=new Map();responses.flatMap(response=>response.messages||[]).forEach(message=>{const key=`${message.platform}:${message.conversationId}`;if(!latest.has(key)){const incoming=message.action==='received';latest.set(key,{clientId:client.id,platform:message.platform,conversationId:message.conversationId,recipientId:incoming?message.senderId:message.recipientId,name:incoming?message.senderDetails?.name:message.recipientDetails?.name,message:message.message||'',created:message.created||'',action:message.action});}});window.liveConversations=[...latest.values()];if(!window.liveConversations.length){list.textContent='No active conversations found on linked messaging accounts.';status.textContent='No messages returned.';return;}list.innerHTML=window.liveConversations.map((item,index)=>`<button class="live-inbox-item" type="button" data-live-conversation="${index}"><b>${escapeHtml(item.name||item.platform)}</b><span>${escapeHtml(item.message)}</span><small>${escapeHtml(item.platform)} · ${escapeHtml(item.created)}</small></button>`).join('');status.textContent=`${window.liveConversations.length} active conversations · ${client.name}`;}catch(error){status.textContent=error.message;list.textContent='Could not load conversations.';}}
